statuses=Counter(s['status'] for r in rows for s in r['field_status'].values())
assert statuses=={'source_backed':45,'source_backed_with_caveat':798,'unresolved':457}
labels={'purpose':'What it does','auth_methods':'Auth','access_model':'Access','api_available':'API availability','api_types':'API Type','api_breadth':'API Breadth','mcp_available':'MCP availability','mcp_provider':'MCP provider','mcp_ownership':'MCP ownership','mcp_notes':'MCP notes','buildability':'Documentation-based Readiness','buildability_rationale':'Readiness rationale','primary_blocker':'Main Blocker'}
groups={'likely_buildable_from_public_docs':'Likely buildable','buildable_with_documented_constraints':'Buildable with constraints','gated_or_outreach_required':'Gated or outreach','needs_further_investigation':'Needs investigation','unresolved':'Unresolved'}
def supported(r,f):return r['field_status'][f]['status']!='unresolved'
def metric(f,extract):
 eligible=[r for r in rows if supported(r,f)]
 values={}
 for r in eligible:
  for v in set(extract(r['findings'][f])):values.setdefault(v,[]).append(r['id'])
 return {'field':f,'denominator':len(eligible),'eligible_ids':[r['id'] for r in eligible],'unresolved':100-len(eligible),'unresolved_ids':[r['id'] for r in rows if not supported(r,f)],'values':{k:{'count':len(v),'ids':v} for k,v in sorted(values.items())},'boundary':'Stored source_backed or source_backed_with_caveat field only; overlapping labels counted once per app. Not population accuracy.'}
m={'auth':metric('auth_methods',lambda v:v),'protocol':metric('api_types',lambda v:v),'access':metric('access_model',lambda v:[a['gate'] for a in v]),'readiness':metric('buildability',lambda v:[v]),'mcp_availability':metric('mcp_available',lambda v:[v]),'mcp_provider':metric('mcp_provider',lambda v:[a['surface'] for a in v]),'mcp_ownership':metric('mcp_ownership',lambda v:[a['surface'] for a in v])}
gate_sets=[{a['gate'] for a in r['findings']['access_model']} for r in rows if supported(r,'access_model')]
gate_ids={r['id']:{a['gate'] for a in r['findings']['access_model']} for r in rows if supported(r,'access_model')}
noncred={'paid_plan','admin_permission','public_app_review','partner_approval','sales_contact','trial','configuration'}
access_buckets={'credential creation only':[i for i,g in gate_ids.items() if g=={'credential_creation'}],'additional recorded gate':[i for i,g in gate_ids.items() if g & noncred],'other recorded access':[i for i,g in gate_ids.items() if g!={'credential_creation'} and not g & noncred]}
m['access_buckets']={k:{'count':len(v),'ids':v} for k,v in access_buckets.items()}
# Coarse text mentions, deliberately not a validated endpoint/action census.
breadth_rules={'records and customers':r'\b(record\w*|contact\w*|customer\w*|lead\w*|deal\w*)\b','messages and support':r'\b(message\w*|conversation\w*|ticket\w*|thread\w*|email\w*|chat\w*)\b','files and documents':r'\b(files?|documents?|notebooks?|transcripts?)\b','commerce and money':r'\b(product\w*|order\w*|payment\w*|invoice\w*|sale\w*|subscription\w*|transaction\w*)\b','automation and jobs':r'\b(workflow\w*|session\w*|generation\w*|actor\w*|scrap\w*|webhook\w*)\b','identity and administration':r'\b(user\w*|team\w*|permission\w*|scope\w*|token\w*|key\w*)\b'}
blocker_rules={'roles, scopes and permissions':r'\b(admin\w*|role\w*|scope\w*|permission\w*|authorization|consent)\b','plans and commercial entitlement':r'\b(paid|plan\w*|enterprise|subscription\w*|contract\w*|credit\w*|eligibility|entitlement)\b','review, partner or outreach':r'\b(review|approval|partner\w*|outreach|support|registration)\b','setup, configuration or version':r'\b(configur\w*|redirect\w*|version\w*|deprecated|migration|onboarding)\b'}
def mentions(f,rules):
 ids=[r['id'] for r in rows if supported(r,f)]
 vals={k:[r['id'] for r in rows if supported(r,f) and re.search(p,r['findings'][f],re.I)] for k,p in rules.items()}
 return {'field':f,'denominator':len(ids),'eligible_ids':ids,'unresolved':100-len(ids),'rules':rules,'values':{k:{'count':len(v),'ids':v} for k,v in vals.items()},'unclassified_ids':[i for i in ids if all(i not in v for v in vals.values())],'boundary':'Overlapping case-insensitive text-mention groups; not confirmed resource/action coverage or universal integration gates.'}
m['breadth_mentions']=mentions('api_breadth',breadth_rules)
m['blocker_mentions']=mentions('primary_blocker',blocker_rules)
cats=[]
for c in dict.fromkeys(r['category'] for r in rows):
 z=[r for r in rows if r['category']==c]
 cats.append({'category':c,'denominator':len(z),'ids':[r['id'] for r in z],'supported_counts':{f:sum(supported(r,f) for r in z) for f in fields},'readiness':dict(Counter(r['findings']['buildability'] for r in z))})
all_groups={k:[r['id'] for r in rows if r['findings']['buildability']==k] for k in groups}
save('patterns.json',{'input_sha256':sha(INPUT/'final-corrected-dataset.json'),'records':100,'field_dispositions':1300,'status_counts':dict(statuses),'field_coverage':{f:dict(Counter(r['field_status'][f]['status'] for r in rows)) for f in fields},'metrics':m,'categories':cats,'candidate_groups':all_groups,'rules':'Eligibility is field-specific. Labels overlap except readiness and access buckets. Unresolved is never no/zero. Readiness is the unchanged stored inference, including apparent inconsistencies; no new completeness threshold.'})

def safeurl(u):
 try:
  p=urlsplit(u)
  if p.scheme not in ('http','https') or not p.hostname or p.username or p.password:return None
  if p.hostname.lower() in ('localhost','127.0.0.1'):return None
  return urlunsplit((p.scheme,p.netloc,p.path,'',''))
 except ValueError:return None
def cleantext(v):
 t=str(v)
 t=re.sub(r'https?://[^\s<>"\']+',lambda q:safeurl(q[0]) or '[URL omitted]',t)
 t=re.sub(r'(?<![A-Za-z])[A-Za-z]:[\\/][^\s;<>]*','[local reference omitted]',t)
 return t
def value(v):
 if isinstance(v,list):
  if not v:return 'Unresolved'
  if isinstance(v[0],dict):return '; '.join(cleantext(a.get('qualification',a.get('note',a.get('gate','')))) for a in v)
  return ', '.join(str(a).replace('_',' ') for a in v)
 return 'Unresolved' if v in ('unknown','unresolved') else cleantext(v)
def pill(st):return '<small class="state '+st+'">'+{'source_backed':'Source backed','source_backed_with_caveat':'Caveated','unresolved':'Unresolved'}[st]+'</small>'
def fieldcell(r,f,short=False):
 s=r['field_status'][f]['status'];v=r['findings'][f]
 text=groups.get(v,v) if isinstance(v,str) and f=='buildability' else value(v)
 if short and len(str(text))>170:
  text='<details><summary>'+esc(str(text)[:145])+'…</summary>'+esc(text)+'</details>'
 else:text=esc(text)
 return text+pill(s)
def table(headers,data):return '<div class="scroll"><table><thead><tr>'+''.join('<th scope="col">'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in data)+'</tbody></table></div>'
