 cells=[esc(r['app']),esc(r['category']),fieldcell(r,'purpose',True),fieldcell(r,'auth_methods'),fieldcell(r,'access_model',True),fieldcell(r,'api_types'),fieldcell(r,'api_breadth',True),'<details><summary>'+esc(value(r['findings']['mcp_available']))+pill(r['field_status']['mcp_available']['status'])+'</summary>'+''.join('<p>'+esc(labels[f])+': '+fieldcell(r,f)+'</p>' for f in ['mcp_provider','mcp_ownership','mcp_notes'])+'</details>',fieldcell(r,'buildability')+'<details><summary>Rationale</summary>'+fieldcell(r,'buildability_rationale')+'</details>',fieldcell(r,'primary_blocker',True),'<details><summary>Inspect 13 fields</summary>'+detail+'</details>',status]
