section('limits','Limitations, unresolved cases and pipeline failures','''<p><strong>Paygent Connect:</strong> identity ambiguity persists despite a candidate product page. <strong>iPayX:</strong> official docs remain unreadable. Neither is force-filled. <strong>Amazon:</strong> developer registration and authorization are documented, while universal public-listing policy applicability conflicts across official guidance. <strong>Clay:</strong> Enterprise table entitlement conflicts with earlier University text. <strong>Datadog:</strong> current legacy keys / service-account tokens must be separated from planned M2M OAuth migration.</p><p>API credit exhaustion prevented semantic completion; unreadable pages, ambiguous products, adjacent-product/token-management contamination and unsupported protocol/MCP inference explain other misses. The corrected dataset preserves independent field evidence without imposing exhaustive route closure. API breadth can remain too coarse for action design, and unknown main blocker does not mean “no blocker.” No integrations, full prerequisite inventories or exhaustive endpoints were certified.</p>'''+coverage+'<p>The recovered original assignment contains rows 1–90; the retained reconciliation records user confirmation for the final ten accepted identities. All 100 are represented. This artifact uses the accepted dataset without resolving additional app facts.</p>')
section('proof','Reproducibility, repository and trigger proof','''<p><a href="https://github.com/udaySuryaP/composio-research-assessment" target="_blank" rel="noopener noreferrer">Source repository</a>. The new correction layers and this final build remain local, untracked and uncommitted; the public repository and older live page do not yet contain this artifact.</p><p>Research trigger: <code>python -m agent.production_research --run-id &lt;new-run-id&gt;</code>. Continuations use checkpoint resume; do not rerun accepted research to reproduce this page. Retained scripts: <code>agent/stage02.py</code>, <code>agent/production_research.py</code>, <code>agent/production_qa.py</code>, and frozen Composio augmentation checkpoints. Research calls require credentials; offline analysis and tests do not.</p><p>From the correction checkout with Python 3.10+ and the established test dependencies: <code>python -B final_build.py</code> rebuilds only this separate final artifact, and <code>python -B -m unittest discover -s tests -v</code> runs the existing suite. <code>final-artifact-20260917/patterns.json</code> includes each eligible denominator, numerator app IDs and text-match rules. The downloaded reviewed data includes public-safe values, reasons and field evidence.</p><details><summary>Exact accepted input and checkout</summary><p>Branch: <code>correction/research-coverage</code>; base: <code>83bd643b087da28d2e1ed1439e381b3a8a9bca7f</code>.</p><p>Accepted input: <code>data/correction/fresh-independent-verification-20260917/final-corrected-dataset.json</code>; SHA-256: <code>'''+sha(INPUT/'final-corrected-dataset.json')+'''</code>. The retained verification and correction ledgers preserve pre-review judgments; rebuilding does not change them.</p></details><p>Delivery state: local review artifact only. No deployment, publishing, README/Notion update, Desktop copy, commit, merge, push or form submission in this stage.</p>''')
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f7f7f2;color:#183029;font:16px/1.6 system-ui,-apple-system,Segoe UI,sans-serif}main{max-width:1240px;margin:auto;padding:48px 32px}header{padding:32px 0 24px;border-bottom:2px solid #183029}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.12em;color:#426158}h1{font-size:clamp(32px,4.2vw,54px);line-height:1.12;letter-spacing:-.035em;max-width:1000px;margin:24px 0}h2{font-size:29px;line-height:1.25;letter-spacing:-.02em;margin:0 0 20px}h3{font-size:20px;line-height:1.3}.lede{font-size:19px;max-width:830px;color:#42584f}section{padding:42px 0;border-bottom:1px solid #c9d3cb;scroll-margin-top:28px}p{max-width:1000px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:30px 0}.stats b{display:block;font-size:28px}.stats span{font-size:13px;color:#42584f}.summary{padding-left:22px;max-width:1030px}.summary li{margin:12px 0}.note{border-left:3px solid #397557;padding-left:18px}.muted{font-size:13px;color:#42584f}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.grid:has(article:nth-child(2):last-child){grid-template-columns:repeat(2,minmax(0,1fr))}a{color:#146749;text-underline-offset:3px}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #bf7120;outline-offset:3px}nav{display:flex;flex-wrap:wrap;gap:10px 22px;padding:24px 0;font-size:14px}table{border-collapse:collapse;width:100%;font-size:13px}th{text-align:left;background:#e4ece5;font-weight:650}td,th{padding:12px 10px;border-bottom:1px solid #d2dbd3;vertical-align:top}td{overflow-wrap:anywhere}details{margin:8px 0}summary{cursor:pointer;font-weight:550}details p{font-size:13px}details ul{padding-left:20px}.group{border-bottom:1px solid #d2dbd3;padding:12px 0}.group summary{font-size:17px}.group p{font-size:15px}.scroll{overflow:auto}.state{display:block;width:fit-content;margin-top:6px;padding:2px 7px;border-radius:4px;font-size:10px;white-space:nowrap}.source_backed{background:#d4e9d8;color:#19482c}.source_backed_with_caveat{background:#f3e5c8;color:#665015}.unresolved{background:#e6e6e2;color:#454b46}.controls{display:flex;flex-wrap:wrap;gap:12px;align-items:flex-end;margin:22px 0}label{display:flex;flex-direction:column;font-size:13px}input,select,button{font:inherit;padding:10px;border:1px solid #a4b3a7;background:white;border-radius:5px;max-width:100%}button{cursor:pointer;background:#183f30;color:white}.matrix-scroll{overflow:auto;max-height:850px;border:1px solid #c9d3cb}#matrix-table{min-width:2400px}#matrix-table th{position:sticky;top:0;z-index:2}#matrix-table td:first-child{font-weight:650;min-width:140px}#matrix-table td:nth-child(11){min-width:280px}#matrix-table tr:target{background:#fff3d8}#matrix-table td{min-width:160px}.evidence p{font-size:12px;line-height:1.5}code{font-size:12px;overflow-wrap:anywhere}footer{padding:30px 0;font-size:13px;color:#42584f}[hidden]{display:none!important}@media(max-width:700px){main{padding:24px 18px}.stats{grid-template-columns:repeat(2,1fr)}.grid,.grid:has(article:nth-child(2):last-child){grid-template-columns:1fr}section{padding:30px 0}h2{font-size:25px}.controls{display:grid;grid-template-columns:1fr;width:100%}input,select{width:100%}.scroll{margin-right:-2px}.matrix-scroll{max-height:none;overflow:visible;border:0}#matrix-table{min-width:0;display:block}#matrix-table thead{display:none}#matrix-table tbody{display:block}#matrix-table tr{display:block;border:1px solid #becdc0;border-radius:8px;padding:14px;margin-bottom:16px;background:white}#matrix-table td,#matrix-table td:first-child,#matrix-table td:nth-child(11){display:block;min-width:0;padding:10px 0;border-bottom:1px solid #e3e9e3}#matrix-table td:before{content:attr(data-label);display:block;font-size:11px;letter-spacing:.04em;text-transform:uppercase;font-weight:700;color:#52685a;margin-bottom:4px}}@media print{nav,.controls{display:none}.matrix-scroll{max-height:none}details{break-inside:avoid}main{padding:0}}'''
js='''const rows=[...document.querySelectorAll('#matrix-table tbody tr')];const search=document.getElementById('search'),category=document.getElementById('category'),readiness=document.getElementById('readiness');function apply(){let n=0;for(const r of rows){const ok=r.dataset.search.includes(search.value.trim().toLowerCase())&&(!category.value||r.dataset.category===category.value)&&(!readiness.value||r.dataset.group===readiness.value);r.hidden=!ok;if(ok)n++;}document.getElementById('result').textContent=n+' of 100 apps';}for(const e of [search,category,readiness])e.addEventListener('input',apply);document.getElementById('reset').onclick=()=>{search.value='';category.value='';readiness.value='';apply();};document.getElementById('download').onclick=()=>{const blob=new Blob([document.getElementById('reviewed-data').textContent],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='composio-reviewed-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};window.addEventListener('hashchange',()=>{const r=document.querySelector(location.hash.startsWith('#app-')?location.hash:'#app-0');if(r){document.getElementById('reset').click();r.scrollIntoView({block:'center'});}});'''
payload={'input_sha256':sha(INPUT/'final-corrected-dataset.json'),'rows':public_rows,'patterns':read(OUT/'patterns.json'),'verification':{'wording':'Purposive risk sample; not whole-dataset accuracy; corrected values are not fresh successes; not fully blinded; agent source review, not fresh human verification.','original_outcomes':hand['pre_review_outcomes'],'appropriately_unresolved':6}}
nav='<nav aria-label="Report sections">'+''.join('<a href="#'+i+'">'+t+'</a>' for i,t in [('summary','Summary'),('findings','Findings'),('candidates','Candidates'),('categories','Categories'),('workflow','Workflow'),('verification','Verification'),('matrix','100-app matrix'),('limits','Limits'),('proof','Proof')])+'</nav>'
doc='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Evidence-grounded API and MCP triage for 100 apps with uncertainty-aware findings."><title>Composio assessment · 100-app integration triage</title><style>'+css+'</style></head><body><main>'+hero+nav+''.join(parts)+'<footer>Research evidence and documentation inference, not executed integration certification. Prepared for review; publication and submission are pending.</footer></main><script id="reviewed-data" type="application/json">'+json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')+'</script><script>'+js+'</script></body></html>'
